import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第50章 五十两天","description":"","frontmatter":{},"headers":[],"relativePath":"第50章_五十两天.md","filePath":"第50章_五十两天.md"}'),_={name:"第50章_五十两天.md"};function u(r,p,q,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第50章-五十两天" tabindex="-1">第50章 五十两天 <a class="header-anchor" href="#第50章-五十两天" aria-label="Permalink to &quot;第50章 五十两天&quot;">​</a></h1><p>一年之约是她先说出口的。</p><p>那天是三月六号，晚上十一点四十。</p><p>她那边刚开学两周，忙得脚不沾地。那晚她上线不到二十分钟，我算过，十九分钟。</p><p>她说，我跟你说个事。</p><p>我说，你说。</p><p>她说，就一年。</p><p>我说，什么一年。</p><p>她说，就一年。一年以后我自己想办法。</p><p>我说，你想什么办法。</p><p>她说，我先不说，说了我又做不到。</p><p>我说，那你为什么说。</p><p>她说，因为我要是不说，你会一直等。</p><p>她说，我不想你一直等一个我不知道的东西。</p><p>我坐在那儿，听她说。</p><p>那时候宿舍里有人在吹风机，很响，另一个人拿梳子梳头，床板一直在动。</p><p>她说，你觉得短也行，长也行，你说个数。</p><p>我说，我不说数。</p><p>她说，为什么。</p><p>我说，你说的一年，我不知道够不够。我要是说不多，像在逼你。我要是说多，像在骗你。</p><p>她没回。</p><p>吹风机的声音停了。</p><p>那二十分钟里最后一条，是她发给我的：好，那就这样。</p><p>第二天晚上她上线，第一件事是补一句。</p><p>她说，我想了一天。</p><p>我说，你说。</p><p>她说，就一年，等我。</p><p>我看到&quot;等我&quot;两个字，坐直了。</p><p>因为她之前所有的说法，都不是&quot;等我&quot;。</p><p>她以前说的是&quot;你别找我&quot;&quot;我告诉你一声&quot;&quot;以后再说&quot;。</p><p>这是第一次她给了一个动作，让我做。</p><p>我说，好。</p><p>我说完以后，我做了一件很蠢的事。</p><p>我拿笔在纸上算。</p><p>一年是三百六十五天。</p><p>我们两个能说话的日子，不是三百六十五天。</p><p>她开学以后只有周日晚上能上线，那是每周一次。</p><p>一次是十九分钟。</p><p>一年有五十二个星期。</p><p>我把五十二写在纸上。</p><p>我看着那个数，看了很久。</p><p>她给我的是三百六十五天，我自己算出来的是五十二天。</p><p>而且这五十二天还不是五十二个白天，是五十二个晚上的最后那二十分钟。</p><p>我把笔放下。</p><p>我想，一个人如果跟你说&quot;就一年&quot;，她心里那个数是三百六十五。</p><p>如果她心里想的是&quot;我们只能见五十二次&quot;，她说不出这句话，她会说不行。</p><p>所以她说的是三百六十五。</p><p>所以我不能告诉她我算的是五十二。</p><p>那天夜里我把这一段写在本子上，写完又翻回去看前面的日期。</p><p>我看到我在二月写过的一个数。</p><p>四十七天。</p><p>她失联的那四十七天，我数的是天。</p><p>现在她回来了，给了我一年，我数的还是天。</p><p>我忽然明白我这一辈子大概只会这一种数法。</p><p>我不会数&quot;我们还在一起多少年&quot;。</p><p>我只会数&quot;我还能等到下一次是几天&quot;。</p><p>第三件事我也没跟她说。</p><p>那年五月有一个周日，那十九分钟里她一句话没说。</p><p>她十一点四十一上线，十一点四十三发了一句。</p><p>她说，在吗。</p><p>我说，在。</p><p>然后没有下文。</p><p>我等到十一点五十二，屏幕没有再亮。</p><p>我以为她被人叫走了。</p><p>十一点五十八，她发了一句。</p><p>她说，我没事。</p><p>她说，我就是想说一句。</p><p>我说，说什么。</p><p>她说，不知道。</p><p>她说，我今天什么也没干，我妈把我电脑收了。</p><p>我说，为什么。</p><p>她说，因为她说我最近不务正业。</p><p>她说，我那一天就在房间里坐了一天。</p><p>她说，我坐了一天，晚上忽然特别想跟你说一句什么。</p><p>她说，我上线以后又不知道该说什么。</p><p>她说，我就把在吗发出去了。</p><p>我说，那你现在可以下了。</p><p>她说，为什么。</p><p>我说，你今天的目的达到了。</p><p>她隔了五秒。</p><p>她说，你这个人。</p><p>那晚她十二点零一分下的。</p><p>比平时多了一分二十秒。</p><p>后来我每想一次那个数，都要笑一下。</p><p>一分二十秒，是那一年里我从她那儿偷到的最大的一笔。</p><p>我把那一段拆开来算过：那一个月里，我一共只偷到过一次零头。</p><p>沈聿是六月里问过我一句话的。</p><p>他说，你们现在到底算什么。</p><p>我说，一年。</p><p>他说，什么一年。</p><p>我说，她说就一年。</p><p>沈聿把书放下，看了我很久。</p><p>他说，你听明白了吗。</p><p>我说，听明白了。</p><p>他说，你明白的是什么。</p><p>我说，她说了一个期限。</p><p>他说，她给你的是一个到日子就可以不说话的东西。</p><p>他说，你拿它当承诺。</p><p>我说，那你说我该拿它当什么。</p><p>他说，你应该当它是她今天能给你的最大的一块。</p><p>他说，你别要求一块石头自己长出来。</p><p>那天晚上我把这句话拿本子记下来。</p><p>记完我自己在旁边写了一行小字。</p><p>我写：他把话说得很好，但是他不知道这块石头多重。</p><p>那一年里，我把每周的十九分钟拆成了三份。</p><p>第一份三分钟，我说这周发生了什么。</p><p>第二份三分钟，我说我算的一道题、看的一页书、驿站的一个小伙子。</p><p>剩下的十三分钟，全部给她。</p><p>十三分钟，是我从一年里抢出来的东西。</p><p>到那年十月，我发现我错了。</p><p>我错在以为她也会拆。</p><p>她从来不拆。</p><p>她是那种攒够了一个星期，然后在十九分钟里一股脑倒出来的人。</p><p>倒完她说，我今天说太多了。</p><p>我说，没有。</p><p>她说，你别安慰我。</p><p>我说，我没安慰，我在记。</p><p>她说，你记这些干什么。</p><p>我说，你下次不说的时候我看。</p><p>她那天晚上的最后一条，隔了很久才发。</p><p>她说，你别这样。</p><p>我问，哪样。</p><p>她说，你这样我走不了了。</p><p>我看到这六个字，手停在屏幕上。</p><p>我说，那你别走。</p><p>这五个字我打了。</p><p>我打了，看见了，也发出去了。</p><p>那一秒我知道我完了。</p><p>因为这不是我平时的做法。</p><p>三秒钟以后，屏幕上出现了一行字。</p><p>她说，你撤回。</p><p>我说，我不撤。</p><p>她说，你撤回，我就当你没说。</p><p>我说，为什么。</p><p>她说，因为我要是接了，我今天就得给你一个回答。</p><p>她说，我给不了。</p><p>我说，你不用回答，你不用说一样。</p><p>她说，你让我说一样，我说了我就得做到。</p><p>她说，我这辈子做不到一件我说出来的事。</p><p>她说，你别让我在你这儿破例，破了例我会恨你。</p><p>那晚她下线的时候是十一点五十九。</p><p>我在黑暗里坐着，听见下铺那个人翻身。</p><p>我那天学会的事是：有些人给不了你回答，不是因为不想给，是因为她一旦说了，她就要拿往后所有的日子去还。</p><p>而她连自己现在这几天都还不起。</p><p>所以她说&quot;你撤回&quot;。</p><p>所以我没撤。</p><p>所以她后来恨过我。</p>',147)])])}const l=t(_,[["render",u]]);export{d as __pageData,l as default};
